import{_ as t,o as u,c as q,ag as a}from"./chunks/framework.CukOUUOK.js";const g=JSON.parse('{"title":"致命的自负：从洛克到列宁，一条两百年前的分岔路与它的历史代价","description":"一、一个反直觉的历史事实 约翰·洛克生于1632年，弗拉基米尔·列宁生于1870年。两人相隔两百多年。按常理，后来者应当能吸收前人的经验教训，设计出更完善的制度。但历史给出的答案恰恰相反：依据洛克原则…","frontmatter":{"title":"致命的自负：从洛克到列宁，一条两百年前的分岔路与它的历史代价","categories":"权力与制度","tags":["政治思想史","制度","历史"],"description":"一、一个反直觉的历史事实 约翰·洛克生于1632年，弗拉基米尔·列宁生于1870年。两人相隔两百多年。按常理，后来者应当能吸收前人的经验教训，设计出更完善的制度。但历史给出的答案恰恰相反：依据洛克原则…","date":"2026-08-27T12:00:00.000Z"},"headers":[],"relativePath":"posts/2026-08-27-fatal-conceit-locke-to-lenin.md","filePath":"posts/2026-08-27-fatal-conceit-locke-to-lenin.md","lastUpdated":1789992750000}'),r={name:"posts/2026-08-27-fatal-conceit-locke-to-lenin.md"};function p(n,o,e,s,l,i){return u(),q("div",null,[...o[0]||(o[0]=[a('<h1 id="致命的自负-从洛克到列宁-一条两百年前的分岔路与它的历史代价" tabindex="-1">致命的自负：从洛克到列宁，一条两百年前的分岔路与它的历史代价 <a class="header-anchor" href="#致命的自负-从洛克到列宁-一条两百年前的分岔路与它的历史代价" aria-label="Permalink to &quot;致命的自负：从洛克到列宁，一条两百年前的分岔路与它的历史代价&quot;">​</a></h1><h2 id="一、一个反直觉的历史事实" tabindex="-1">一、一个反直觉的历史事实 <a class="header-anchor" href="#一、一个反直觉的历史事实" aria-label="Permalink to &quot;一、一个反直觉的历史事实&quot;">​</a></h2><p>约翰·洛克生于1632年，弗拉基米尔·列宁生于1870年。两人相隔两百多年。按常理，后来者应当能吸收前人的经验教训，设计出更完善的制度。但历史给出的答案恰恰相反：依据洛克原则建立的美国，比依据列宁原则建立的苏联更繁荣、更稳定、更持久。</p><p>这不是偶然。两条道路在起点上就已经分岔了，而分岔的方向决定了此后一切制度后果。要理解这个分岔，需要先回到两条路线各自的思想源头，再审视围绕这个分岔产生的持续了两个世纪的争论——其中既有来自外部的批评，也有来自内部的警告。而这一切争论的思想根基，可以进一步追溯到马克思对洛克传统的批判，以及这场批判本身所蕴含的致命自负。</p><h2 id="二、两条分岔路的起点" tabindex="-1">二、两条分岔路的起点 <a class="header-anchor" href="#二、两条分岔路的起点" aria-label="Permalink to &quot;二、两条分岔路的起点&quot;">​</a></h2><h3 id="洛克的起点-人是目的-权力是工具" tabindex="-1">洛克的起点：人是目的，权力是工具 <a class="header-anchor" href="#洛克的起点-人是目的-权力是工具" aria-label="Permalink to &quot;洛克的起点：人是目的，权力是工具&quot;">​</a></h3><p>洛克政治哲学的核心命题是：<strong>每个人天然拥有生命、自由和财产的权利，这些权利先于政府而存在。</strong> 政府是人民为了保护这些权利而创造的工具。工具不能反过来主宰创造它的人。</p><p>这个起点直接推导出三个制度原则：权力是有限的——因为它只是工具；权力必须分立——因为&quot;如果同一批人同时拥有制定和执行法律的权力，这就会给人们的弱点以绝大诱惑&quot;；权力必须可被挑战——&quot;任何形式的政府，一旦破坏这些目标，人民就有权利去改变它或废除它。&quot;</p><p>洛克对人性的假设也很关键：人是自利的、理性的，但也是脆弱的——&quot;较为强壮或聪明的人通常企图剥夺弱者的生命、自由和财产&quot;。正因为人性不可信任，所以<strong>任何掌握权力的人都不可信任</strong>，制度设计的出发点就是防范权力被滥用。</p><h3 id="列宁的起点-先锋队知道真理-人民需要被引导" tabindex="-1">列宁的起点：先锋队知道真理，人民需要被引导 <a class="header-anchor" href="#列宁的起点-先锋队知道真理-人民需要被引导" aria-label="Permalink to &quot;列宁的起点：先锋队知道真理，人民需要被引导&quot;">​</a></h3><p>列宁的起点完全不同。他在《怎么办？》（1902年）中提出了一个根本不同的命题：<strong>工人阶级仅凭自身力量只能产生&quot;工联主义意识&quot;，无法自发产生革命意识。</strong> 革命意识必须由一批掌握马克思主义理论的职业革命家——&quot;先锋队&quot;——从外部&quot;灌输&quot;进去。</p><p>这个起点推导出截然相反的制度原则：权力是无限的——因为先锋队掌握了历史发展的规律，代表了无产阶级的根本利益，它的权力不需要被限制；权力必须集中——民主集中制在实践中变成了&quot;集中&quot;压倒&quot;民主&quot;，列宁在1921年俄共十大上禁止党内派别活动，这一&quot;临时&quot;禁令直到1989年才解除；权力不可被挑战——1977年苏联宪法第六条明确规定苏共是&quot;苏联社会的领导和指导力量&quot;，当党的领导的地位被写入宪法，任何挑战党的行为就不仅是政治错误，而且是违宪行为。</p><h3 id="两条路线的制度后果" tabindex="-1">两条路线的制度后果 <a class="header-anchor" href="#两条路线的制度后果" aria-label="Permalink to &quot;两条路线的制度后果&quot;">​</a></h3><p>把这两套起点放在一起对比，制度后果的差异就清晰了：</p><p>洛克传统列宁传统权力的性质工具——人民创造政府来服务自己目的——先锋队代表历史规律来改造社会对人性的假设不可信任——所以权力必须被制约可改造——所以先锋队有权教育人民纠错机制内生的——选举、司法审查、言论自由、权力分立外生的——只能靠领导人自我觉悟或外部冲击合法性来源程序性的——被统治者的同意实质性的——代表历史发展方向当权力犯错时可以通过制度内部机制纠正没有制度化的纠错渠道，只能等到危机爆发洛克传统的设计逻辑是：我不信任任何掌握权力的人，所以我要设计一套制度，让权力之间互相制约，让公民有权挑战权力。这套制度不依赖于&quot;好人执政&quot;——即使执政者是庸才甚至坏人，制度的制衡机制也能防止他造成太大破坏。</p><p>列宁传统的设计逻辑是：先锋队掌握了真理，所以应该把权力集中到先锋队手中，由先锋队来领导人民走向光明。这套制度高度依赖&quot;好人执政&quot;——如果先锋队本身出了问题（腐败、僵化、脱离群众），没有任何制度化的机制可以纠正它。</p><p><strong>一百多年后回头看，洛克传统的制度不依赖于&quot;谁在掌权&quot;，而列宁传统的制度高度依赖于&quot;谁在掌权&quot;。</strong> 这就是稳定性差异的根源。</p><h2 id="三、列宁的思想源头-从卢梭的-公意-到马克思的-历史规律" tabindex="-1">三、列宁的思想源头：从卢梭的&quot;公意&quot;到马克思的&quot;历史规律&quot; <a class="header-anchor" href="#三、列宁的思想源头-从卢梭的-公意-到马克思的-历史规律" aria-label="Permalink to &quot;三、列宁的思想源头：从卢梭的&quot;公意&quot;到马克思的&quot;历史规律&quot;&quot;">​</a></h2><p>列宁并非凭空创造了&quot;先锋队&quot;概念。他的思想源头有两条线索，一条来自卢梭，一条来自马克思。</p><h3 id="卢梭的-公意" tabindex="-1">卢梭的&quot;公意&quot; <a class="header-anchor" href="#卢梭的-公意" aria-label="Permalink to &quot;卢梭的&quot;公意&quot;&quot;">​</a></h3><p>卢梭在《社会契约论》中提出了&quot;公意&quot;（general will）这个概念。他的定义是：公意不是&quot;众意&quot;——不是所有人个别意志的简单加总——而是剔除了相互矛盾的私人利益之后，剩下的那个指向公共利益的共同部分。卢梭说公意&quot;永远是正确的&quot;，服从公意就是服从自己的&quot;更高自我&quot;，因此&quot;强迫你服从公意&quot;等于&quot;强迫你自由&quot;。</p><p>列宁几乎照搬了这个逻辑结构：人民被资本主义意识形态蒙蔽，无法自发认识自己的&quot;真正利益&quot;；先锋队掌握了真理，有权替人民做主；即使工人阶级当下不理解、不支持，先锋队也要替他们实现&quot;根本利益&quot;。</p><p>有学者直接指出：<strong>&quot;这是柏拉图主义在启蒙运动时代的回响：哲人王的形象以拥有&#39;高级智慧&#39;、受神指引的&#39;立法者&#39;出现在卢梭的著作中；又以&#39;先锋队&#39;的形象被列宁复兴。&quot;</strong></p><p>以赛亚·伯林在《自由及其背叛》中将卢梭列为&quot;人类自由的六个敌人&quot;之一，正是因为他看穿了这套逻辑的危险性：</p><blockquote><p>&quot;卢梭自称是有史以来最激越和最强烈地热爱人类自由的人……尽管如此，在整个现代思想史上，卢梭是自由最险恶和最可怕的一个敌人。&quot;</p></blockquote><p>伯林的核心论点是：卢梭把&quot;真实自我&quot;（理性的、道德的）和&quot;经验自我&quot;（被欲望支配的）做了分裂，然后声称服从&quot;真实自我&quot;才是真正的自由。这就打开了一个可怕的逻辑缺口——<strong>如果有人声称比你自己更了解你的&quot;真实自我&quot;，他就可以以&quot;解放你&quot;的名义强制你。</strong></p><p>这个逻辑从卢梭到列宁一脉相承：卢梭说&quot;你以为你想要的是私人利益，但你的&#39;真正意志&#39;是公意&quot;；列宁说&quot;你以为你想要的是涨工资、改善条件，但你的&#39;真正利益&#39;是推翻资本主义&quot;。两者都声称自己在&quot;解放&quot;人民，但两者的逻辑都允许一个外部权威以&quot;你真正想要的&quot;为名，压制你实际表达的意愿。</p><h3 id="马克思的-历史规律" tabindex="-1">马克思的&quot;历史规律&quot; <a class="header-anchor" href="#马克思的-历史规律" aria-label="Permalink to &quot;马克思的&quot;历史规律&quot;&quot;">​</a></h3><p>马克思为列宁的先锋队理论提供了另一条思想线索。马克思在《共产党宣言》中有一段关于共产党人角色的经典表述：</p><blockquote><p>&quot;共产党人不是同其他工人政党相对立的特殊政党。他们没有任何同整个无产阶级的利益不同的利益。他们不提出任何特殊的原则，用以塑造无产阶级的运动。……在实践方面，共产党人是各国工人政党中最坚决的、始终起推动作用的部分；在理论方面，他们胜过其余无产阶级群众的地方在于他们了解无产阶级运动的条件、进程和一般结果。&quot;</p></blockquote><p>这段话看起来确实有&quot;先锋队&quot;的味道——共产党人是&quot;最坚决的&quot;部分，在理论上&quot;胜过&quot;其余群众。但仔细读，有几个关键限定：共产党人不是&quot;对立的特殊政党&quot;，他们和无产阶级是同一支队伍；他们&quot;没有任何同整个无产阶级的利益不同的利益&quot;；他们&quot;不提出任何特殊的原则，用以塑造无产阶级的运动&quot;。</p><p>马克思和恩格斯从未建议共产党人应该形成一个排他性的少数派，他们也不应该阻止工人阶级的自发运动。</p><p>列宁在《怎么办？》中做了一个关键的逻辑跳跃：</p><blockquote><p>&quot;各国的历史都证明：工人阶级单靠自己本身的力量，只能形成工联主义的意识……而社会主义学说则是从有产阶级的有教养的人即知识分子创造的哲学理论、历史理论和经济理论中发展起来的。&quot;</p></blockquote><p>由此列宁推导出：<strong>&quot;阶级政治意识只能从外面灌输给工人，即只能从经济斗争外面，从工人同厂主的关系范围外面灌输给工人。&quot;</strong></p><p>从马克思到列宁，至少有三步关键跳跃：</p><ul><li><strong>第一步</strong>：从&quot;共产党人在理论上领先&quot;→&quot;工人阶级自身不可能产生社会主义意识&quot;。马克思说共产党人&quot;了解&quot;运动的条件和结果，但从未说工人阶级&quot;不可能&quot;自己产生这种了解。</li><li><strong>第二步</strong>：从&quot;社会主义意识需要从外部灌输&quot;→&quot;必须建立一个由职业革命家组成的集中制政党来执行灌输&quot;。即使承认灌输的必要性，也不能自动推导出需要一个凌驾于工人运动之上的独立组织。</li><li><strong>第三步</strong>：从&quot;先锋队代表无产阶级的利益&quot;→&quot;先锋队有权替无产阶级做主，即使无产阶级自己不认同&quot;。这一步是最危险的——它把&quot;代表&quot;变成了&quot;替代&quot;。</li></ul><p>马克思本人从未设计过具体的制度方案。他批判了资本主义，预言了共产主义，但他没有写过&quot;共产主义宪法&quot;，没有设计过权力如何分配、如何制衡、如何防止滥用的具体机制。他留下的更多是哲学批判和经济学分析，而不是制度蓝图。是列宁把马克思的哲学变成了制度，而在制度设计上，列宁并没有遵循马克思的某些核心洞见，反而继承了卢梭&quot;公意&quot;概念的逻辑结构——预设一个超越性的&quot;历史规律&quot;，指定一个主体（先锋队）来代表它，然后跳过&quot;谁来审查审查者&quot;这个问题。</p><h2 id="四、那个没有被追问的问题" tabindex="-1">四、那个没有被追问的问题 <a class="header-anchor" href="#四、那个没有被追问的问题" aria-label="Permalink to &quot;四、那个没有被追问的问题&quot;">​</a></h2><p>卢梭的&quot;公意&quot;和列宁的&quot;先锋队&quot;共享同一个致命缺陷：<strong>他们都没有追问那个最根本的问题——这个抽象物到底存不存在？</strong></p><p>卢梭抽象出了&quot;公意&quot;，但没有追问：在一个利益多元、价值分歧的社会里，真的存在一个超越所有私人利益的&quot;共同利益&quot;吗？如果存在，谁能认识它？认识它的标准是什么？如果不存在，那&quot;公意&quot;不过是一个空洞的能指，谁掌握权力谁就可以声称自己代表&quot;公意&quot;。</p><p>列宁抽象出了&quot;先锋队&quot;，但没有追问：这个先锋队凭什么声称自己代表无产阶级的利益？如果无产阶级自己不认同先锋队的判断，先锋队有什么资格替他们做主？先锋队的判断错了怎么办？谁来审查先锋队？</p><p>这两个&quot;没有追问&quot;，在逻辑上是同一个问题：<strong>当一个理论预设了一个超越性的&quot;真正意志&quot;或&quot;真正利益&quot;时，它就必须回答&quot;谁来判定&quot;这个问题。如果回答不了，这个抽象概念就会被任何一个掌握权力的主体所劫持。</strong></p><p>卢梭本人其实意识到了这个问题。他区分了&quot;主权&quot;和&quot;政府&quot;，承认政府（执行者）可能篡夺主权（公意），也承认公意&quot;容易被少数人篡改&quot;。但他给出的解决方案是：定期召集人民集会，让主权者（人民）重新出场，审查政府是否忠实执行了公意。这个方案在实践层面面临根本困难——它没有回答：当人民集会时，谁来判定集会上的多数决定就是&quot;公意&quot;而非&quot;众意&quot;？当不同群体对&quot;公共利益&quot;有不同理解时，谁有最终裁决权？</p><p>卢梭的&quot;立法者&quot;概念进一步暴露了这个困境。立法者负责为人民制定法律、塑造公意，但立法者本身不是主权者，没有立法权——他只能通过非理性的手段说服人民接受法律。那么，<strong>立法者的权威从何而来？他凭什么知道什么是&quot;真正的&quot;公意？</strong> 卢梭没有回答这个问题。</p><h2 id="五、来自内部的警告-卢森堡对列宁的批评" tabindex="-1">五、来自内部的警告：卢森堡对列宁的批评 <a class="header-anchor" href="#五、来自内部的警告-卢森堡对列宁的批评" aria-label="Permalink to &quot;五、来自内部的警告：卢森堡对列宁的批评&quot;">​</a></h2><p>对&quot;先锋队到底能不能代表人民&quot;这个问题的追问，不仅来自自由主义传统的外部批评者，也来自马克思主义传统的内部。罗莎·卢森堡的批评之所以特别重要，正因为她不是站在对立阵营来否定革命，而是站在革命阵营内部来警告革命走样的危险。</p><h3 id="_1904年-对建党原则的第一次公开批判" tabindex="-1">1904年：对建党原则的第一次公开批判 <a class="header-anchor" href="#_1904年-对建党原则的第一次公开批判" aria-label="Permalink to &quot;1904年：对建党原则的第一次公开批判&quot;">​</a></h3><p>1903年，俄国社会民主工党第二次代表大会上，列宁与马尔托夫发生了关于党员资格和党组织原则的激烈争论，布尔什维克和孟什维克由此分裂。1904年，列宁出版《进一步，退两步》，系统阐述了他的建党思想：党必须是无产阶级的先锋队，必须由职业革命家组成核心，必须实行严格的集中制和铁的纪律。</p><p>卢森堡读到这本书后，立即于1904年7月在德国社会民主党理论刊物《新时代》上发表了《俄国社会民主党的组织问题》一文，这是国际社会主义运动中对列宁建党原则的第一次系统性公开批判。</p><p>卢森堡的批评集中在三个层面：</p><p><strong>第一，列宁的集中制是&quot;布朗基主义&quot;的翻版。</strong> 卢森堡认为，列宁所主张的集中制建立在两个基本原则之上：第一，使党的一切组织及其活动，甚至在最微小的细节上，都盲目服从中央机关，这个中央机关单独地为大家思考问题、制定计划和决定事情；第二，把党的有组织的核心同它周围的革命环境严格地隔离开来。在卢森堡看来，这就是&quot;把布朗基密谋集团的运动的组织原则机械地搬到社会民主党的工人群众运动中来&quot;。</p><p>布朗基主义的核心特征是：不依靠工人群众的直接的阶级行动，也不需要群众性的组织，而是由一小撮职业密谋者策划和执行革命。卢森堡认为列宁的先锋队理论在结构上与布朗基主义高度相似——都是由少数精英替多数群众做主。</p><p><strong>第二，中央委员会会异化为党的唯一思考器官。</strong> 卢森堡警告：如果按照列宁的方案，中央委员会将成为&quot;党的唯一的积极核心&quot;，而其他一切组织&quot;只不过是它的执行工具&quot;。党内普通成员将变成&quot;在自己的活动范围以外执行预定的意志的纯粹的执行机器&quot;。这种结构必然导致：中央机关垄断了思考和决策的权力，基层组织丧失了首创精神和独立判断能力，党员从&quot;行动的集体&quot;退化为&quot;中央委员会的工具&quot;。</p><p><strong>第三，群众的自发行动比中央委员会的&quot;正确&quot;更有价值。</strong> 这是卢森堡最著名的一句论断：&quot;真正革命工人运动在历史上所犯的错误，从历史整体来看，远比最优秀中央委员会的绝对正确更有价值。&quot;</p><p>这句话体现了卢森堡与列宁在认识论上的根本分歧：列宁认为革命意识必须由先锋队从外部&quot;灌输&quot;给工人阶级；卢森堡则认为阶级意识是在群众的自发斗争中有机地生长出来的，&quot;不觉悟的人先于觉悟的人，客观历史进程的逻辑先于历史进程的体现者的主观逻辑&quot;。</p><p>列宁在1904年9月写了反驳文章，但《新时代》主编考茨基退了稿。这篇文章直到1930年才首次发表。列宁的反驳核心是：卢森堡完全不了解俄国党的实际情况，她向读者介绍的不是列宁的书，而是&quot;别的什么东西&quot;。列宁指出，俄国社会民主工党当时处于沙皇专制的地下状态，必须有一个高度集中、纪律严密的组织才能生存和斗争。卢森堡从德国社会民主党的合法环境出发来批评俄国党的组织原则，是&quot;无的放矢&quot;。</p><h3 id="_1918年-狱中的《论俄国革命》" tabindex="-1">1918年：狱中的《论俄国革命》 <a class="header-anchor" href="#_1918年-狱中的《论俄国革命》" aria-label="Permalink to &quot;1918年：狱中的《论俄国革命》&quot;">​</a></h3><p>1917年十月革命胜利时，卢森堡被关在德国布勒斯劳监狱中。她对十月革命本身高度肯定，称其为&quot;世界无产阶级第一次真正掌握政权的尝试&quot;，认为&quot;列宁和托洛茨基以及他们的朋友们是第一批给世界无产阶级作出榜样的人&quot;。</p><p>但1918年秋季，她在狱中写下的《论俄国革命》手稿中，对布尔什维克夺取政权后的制度安排进行了严厉批评。这篇手稿在她生前未能发表，直到1922年才由她的友人保尔·列维整理出版——此时卢森堡已于1919年1月15日被右翼民兵组织&quot;自由军团&quot;杀害，年仅47岁。</p><p>卢森堡的批评集中在三个核心问题：</p><p><strong>关于解散立宪会议。</strong> 1918年1月，布尔什维克在立宪会议选举中未能获得多数席位后，以武力解散了立宪会议。卢森堡认为，这一做法开了一个极其危险的先例——它意味着当一个政党无法通过民主程序获得多数支持时，可以选择用暴力手段推翻民主结果。</p><p><strong>关于压制言论自由和党内民主。</strong> 这是卢森堡批评中最深刻、最有预见性的部分。她写道：</p><blockquote><p>&quot;没有普选，没有不受限制的出版和集会自由，没有意见的自由交锋，每一个公共机构中的生命就会消亡，变成一种徒有其表的空壳生活，其中只有官僚主义是活跃的因素。&quot;</p></blockquote><p>她进一步描述了这种制度的必然演变：</p><blockquote><p>&quot;公共生活逐渐沉睡，几十个精力无穷的党的领导人指挥着和统治着。在他们中间，实际上只有十几个杰出人物在领导，而工人阶级的精华不时被邀请参加会议，为领导人的演讲鼓掌，一致通过提出的决议——归根结底，这是一帮人的事——诚然，这是一种专政，但不是无产阶级的专政，而是一小撮政治家的专政，即资产阶级意义上的专政，即雅各宾派统治意义上的专政。&quot;</p></blockquote><p>这段话精确地预言了苏联后来的政治演变：从&quot;无产阶级专政&quot;退化为&quot;党的专政&quot;，再退化为&quot;政治局的专政&quot;，最终退化为&quot;一个人的专政&quot;。</p><p><strong>关于&quot;自由&quot;的本质。</strong> 卢森堡在手稿中写下了她最著名的一句话，也是整个左翼思想史上关于自由最精辟的论述之一：</p><blockquote><p>&quot;只给政府的拥护者以自由，只给一个党的党员（哪怕党员数目很多）以自由，这不是自由。自由始终只是持不同思想者的自由。这不是由于对&#39;正义&#39;的狂热，而是因为政治自由的一切教育的、有益的、净化的作用都同这一本质相联系，如果&#39;自由&#39;成了特权，它就不起作用了。&quot;</p></blockquote><p>这段话的逻辑极其严密：自由的价值不在于它是一种道德权利，而在于它是一种功能性机制——只有当反对派也有表达自由时，公共讨论才能产生教育、纠错和净化的效果。如果自由只给执政者，它就不再是自由，而是特权；一旦自由变成特权，它就丧失了全部政治功能。</p><p>卢森堡还批评了布尔什维克&quot;先夺取政权，再建设民主&quot;的逻辑。她认为：</p><blockquote><p>&quot;社会主义民主不是只在应许之地、在社会主义经济基础创建之后才开始的东西；它不是作为圣诞礼物送给那些在此期间忠诚支持少数社会主义独裁者的值得奖赏的人。社会主义民主与阶级统治的摧毁和社会主义的建设同时开始。&quot;</p></blockquote><p>这个批评的要点是：民主不是革命成功后的&quot;奖赏&quot;，而是革命过程本身的内在要素。如果在革命过程中就取消了民主，那么革命成功后也不会自动产生民主——因为在革命过程中被培养出来的&quot;服从习惯&quot;不会在革命结束后突然消失。</p><h3 id="卢森堡的替代方案-自我集中制" tabindex="-1">卢森堡的替代方案：&quot;自我集中制&quot; <a class="header-anchor" href="#卢森堡的替代方案-自我集中制" aria-label="Permalink to &quot;卢森堡的替代方案：&quot;自我集中制&quot;&quot;">​</a></h3><p>卢森堡并非无政府主义者，她并不反对集中制本身。她反对的是列宁式的&quot;极端集中制&quot;。她提出了自己的替代方案——&quot;自我集中制&quot;（self-centralism）：</p><blockquote><p>&quot;社会民主党的集中制……只能是工人阶级中有觉悟的和正在进行斗争的先锋队的意志的强制性综合……是无产阶级在自己的党组织内部的大多数人的统治。&quot;</p></blockquote><p>她认为，真正的集中制应该是&quot;党中央在集中了党的多数意见的基础上执行多数的意见&quot;，而不是&quot;党中央代替全党来集中&quot;。党的纪律，不是让80万党员去服从一个中央机构，而是相反，所有中央机构都要执行80万党员的意志。</p><h2 id="六、来自外部的追问-罗素对卢梭和苏联的批评" tabindex="-1">六、来自外部的追问：罗素对卢梭和苏联的批评 <a class="header-anchor" href="#六、来自外部的追问-罗素对卢梭和苏联的批评" aria-label="Permalink to &quot;六、来自外部的追问：罗素对卢梭和苏联的批评&quot;">​</a></h2><p>如果说卢森堡是从马克思主义传统内部发出的警告，那么伯特兰·罗素则是从自由主义传统外部进行的系统性追问。两者的结论高度一致，但论证路径截然不同。</p><h3 id="罗素对卢梭的批评" tabindex="-1">罗素对卢梭的批评 <a class="header-anchor" href="#罗素对卢梭的批评" aria-label="Permalink to &quot;罗素对卢梭的批评&quot;">​</a></h3><p>罗素在《西方哲学史》中专门用了一整章来讨论卢梭，批评集中在几个层面。</p><p>他给了卢梭一个极其尖锐的定性：</p><blockquote><p>&quot;他是浪漫主义运动之父，是从人的情感来推断人类范围以外的事实这派思想体系的创始者，还是那种与传统君主专制相反的<strong>伪民主独裁的政治哲学</strong>的发明人。&quot;</p></blockquote><p>&quot;伪民主独裁&quot;——这四个字是罗素对卢梭最核心的判断。表面上是民主的（人民主权、公意），实质上为独裁打开了大门。</p><p>罗素进而画了一条从卢梭到希特勒的思想谱系线：</p><blockquote><p>&quot;从卢梭时代以来，自认为是改革家的人向来分成两派，即追随他的人和追随洛克的人。……在现时，<strong>希特勒是卢梭的一个结果；罗斯福和丘吉尔是洛克的结果</strong>。&quot;</p></blockquote><p>罗素还批评卢梭以情感取代理性作为道德和政治的基础。卢梭认为自然情感能引导人服务于共同利益，理性反而驱使人自私。罗素反驳说：每个人的情感差异很大，由此产生千差万别的道德标准；卢梭直接把情感判定为道德基础，不做任何逻辑推理，因此没有可证伪性——就算他说错了，别人也无法从逻辑上反驳他。罗素甚至认为，就严谨性而言，卢梭的哲学不如托马斯·阿奎那的宗教哲学——因为阿奎那至少是从逻辑推理出发的，如果错误可以被反驳。</p><h3 id="罗素对苏联的批评-亲历之后的幻灭" tabindex="-1">罗素对苏联的批评：亲历之后的幻灭 <a class="header-anchor" href="#罗素对苏联的批评-亲历之后的幻灭" aria-label="Permalink to &quot;罗素对苏联的批评：亲历之后的幻灭&quot;">​</a></h3><p>罗素不是从书斋里批评苏联的。1920年，他作为英国工党代表团成员访问苏俄，在莫斯科和彼得格勒停留了一个月，与列宁进行了长谈。访问之前，他对十月革命抱有期待；访问之后，热情骤灭。回国后他写下了《布尔什维克主义的理论和实践》（<em>The Practice and Theory of Bolshevism</em>，1920年），对苏联制度进行了系统性批判。</p><p>罗素对列宁本人的评价是：列宁有&quot;坚强的意志&quot;，不是一个伪善者。但他紧接着指出：<strong>列宁并不比他与之斗争的人更好。</strong> 列宁推翻了沙皇专制，却建立了一种同样——甚至更加——集中的权力体系。手段变了，权力的本质没有变。</p><p>罗素的批评集中在两个层面：</p><p><strong>人性层面：</strong> 布尔什维克幻想通过宣扬仇恨、以斗争形式促成美好结果——以天下大乱带来天下大治。但罗素指出，那些养成仇恨习惯的人，一旦取得胜利，就会马不停蹄地寻找新的仇恨目标。仇恨不会自动消失，它只会转移对象。</p><p><strong>理论层面：</strong> 布尔什维克认为，只要国家成为唯一的资本家，就能消除剥削和压迫。罗素反驳说，这种做法只是造出了更加可怖的权威——所有人将生杀予夺的大权全部交托给政府官员。消灭私人所有权并不自动消灭支配关系。工厂主可以消失，但如果全部生计都由官僚体系分配，个人面对权力时反而更加无助。</p><p>罗素还直言：<strong>&quot;苏俄的思想压迫比起无论哪一个资本主义国家都更严酷。&quot;</strong></p><p>值得注意的是，罗素在1949年——冷战已经展开、苏联的问题已经充分暴露之后——将这本书一字不改地再版。当年批评他&quot;背叛左翼&quot;的很多左派朋友，此时自己也不再对苏联抱有幻想了。</p><h3 id="罗素自由主义的哲学根基-经验主义如何导向自由主义" tabindex="-1">罗素自由主义的哲学根基：经验主义如何导向自由主义 <a class="header-anchor" href="#罗素自由主义的哲学根基-经验主义如何导向自由主义" aria-label="Permalink to &quot;罗素自由主义的哲学根基：经验主义如何导向自由主义&quot;">​</a></h3><p>罗素的自由主义不是凭空产生的政治偏好，而是从他的认识论立场中逻辑地推导出来的。</p><p>罗素一生的认识论核心目标是寻找绝对确定的知识根基，但最终走向了<strong>温和的怀疑论</strong>。他认为不存在百分之百确定的知识，所有知识都只有概率意义上的可靠性，人类只能通过不断的逻辑检验和经验验证逐步接近真理。</p><p>这个认识论立场直接导向了政治自由主义：</p><blockquote><p><strong>既然没有人能掌握绝对真理，就没有任何权威有权压制不同观点。宽容和自由是保障社会进步的核心前提。</strong></p></blockquote><p>罗素在1947年的文章《哲学与政治》中进一步阐发了这一点。他写道：<strong>唯一能为民主提供理论辩护、且在精神气质上与民主相一致的哲学，就是经验主义。</strong> 洛克作为经验主义的奠基者，清楚地表明了这种哲学与自由和宽容观念之间的密切关联。由此，罗素得出结论：自由主义的本质不在于人们持有什么观点，而在于<strong>如何持有观点</strong>——不是教条地持有，而是试探性地持有。</p><p>这就是洛克传统和卢梭-列宁传统在认识论层面的根本分歧：</p><ul><li><strong>洛克传统</strong>：知识来自经验，经验是有限的、可错的，所以任何声称掌握绝对真理的人都是可疑的。因此权力必须被限制，观点必须自由竞争。</li><li><strong>卢梭-列宁传统</strong>：存在一个可以被认识的&quot;公意&quot;或&quot;历史规律&quot;，先锋队掌握了它，所以先锋队的权力不需要被限制——因为它代表的是&quot;真理&quot;。</li></ul><p>罗素在《西方哲学史》中直接给出了定位：<strong>&quot;必须把洛克看成不但是认识论中经验主义的奠基者，同样也是哲学上的自由主义的始祖。&quot;</strong> 他认为经验主义和自由主义之间存在内在的逻辑关联，而洛克是这两条线索的共同源头。</p><p>罗素自己出身于英国&quot;贵族自由主义传统&quot;的家庭。他的祖父约翰·罗素勋爵是辉格党（自由党前身）著名政治家，维多利亚时代两度出任首相。他的父母是约翰·穆勒（密尔）的狂热追随者。而穆勒的哲学，正是沿着&quot;洛克→贝克莱→休谟→詹姆斯·穆勒→约翰·穆勒&quot;这条英国经验主义路线一路传下来的。罗素把自己放在这条谱系中，绝非偶然。</p><p>在继承洛克传统的基础上，罗素做出了几项重要推进：他将经验主义的认识论与自由主义的政治哲学做了更紧密的逻辑焊接——&quot;经验主义→知识可错→无人掌握绝对真理→权力必须受限→思想必须自由&quot;这条逻辑链在洛克那里是隐含的，在罗素这里被明确表述了。他对&quot;谁来判定公益&quot;这个问题做了更明确的回答——不能让政府自己判定，必须有独立的外部审查机制。他还将洛克传统的核心逻辑应用到了20世纪的新问题上——洛克面对的是王权神授论，罗素面对的是极权主义。</p><h2 id="七、两种批评的交汇与分野" tabindex="-1">七、两种批评的交汇与分野 <a class="header-anchor" href="#七、两种批评的交汇与分野" aria-label="Permalink to &quot;七、两种批评的交汇与分野&quot;">​</a></h2><p>卢森堡和罗素对列宁主义的批评虽然结论相似，但立场和角度截然不同。</p><p>罗素是站在自由主义传统的外部来批评苏联制度的——他从根本上不接受&quot;先锋队代表人民&quot;这个前提，他的批评基于&quot;任何权力都必须受到限制&quot;这个自由主义基本原则，而他的认识论立场——没有人能掌握绝对真理——为这个基本原则提供了哲学根基。</p><p>卢森堡则是站在马克思主义传统的内部来批评列宁的——她本身就是一个革命者，一个共产主义者，她支持十月革命，她反对的是革命之后的制度安排。她的批评不是&quot;反对革命&quot;，而是&quot;反对革命走样&quot;。</p><p>这恰恰使卢森堡的批评更具杀伤力：她不是资产阶级学者在攻击社会主义，而是社会主义者自己在警告社会主义的危险倾向。正如她自己所说，她的批评是&quot;来自内部的纠偏&quot;，而不是&quot;来自外部的否定&quot;。</p><p>但两人也有一个共同的交汇点：<strong>他们都追问了那个卢梭和列宁没有追问的问题——&quot;谁来审查审查者？&quot;</strong> 罗素从认识论上回答了这个问题：不存在绝对真理，所以不存在不需要被审查的权威。卢森堡从政治实践上回答了这个问题：先锋队一旦垄断了权力，就会从&quot;代表人民&quot;异化为&quot;统治人民&quot;，所以必须有不受限制的言论自由和党内民主来防止这种异化。</p><p>列宁对卢森堡的态度始终复杂。他批评过她在民族问题、群众罢工问题、建党问题上的&quot;错误&quot;，但从未否认她的革命品格和理论才华。列宁引用了俄国一个寓言的两句话来评价她：&quot;鹰有时比鸡还飞得低，但鸡永远不能飞得像鹰那样高。&quot;这个评价本身就说明了卢森堡在列宁心目中的地位——她是论敌，但更是值得尊敬的战友。</p><h2 id="八、马克思凭什么判定洛克是-资产阶级" tabindex="-1">八、马克思凭什么判定洛克是&quot;资产阶级&quot;？ <a class="header-anchor" href="#八、马克思凭什么判定洛克是-资产阶级" aria-label="Permalink to &quot;八、马克思凭什么判定洛克是&quot;资产阶级&quot;？&quot;">​</a></h2><p>要理解这条分岔路的深层思想根基，必须追问一个更根本的问题：马克思凭什么把洛克的政治哲学定性为&quot;资产阶级&quot;的？他是否设计了一套比洛克更好的方案？</p><h3 id="马克思对洛克的批判" tabindex="-1">马克思对洛克的批判 <a class="header-anchor" href="#马克思对洛克的批判" aria-label="Permalink to &quot;马克思对洛克的批判&quot;">​</a></h3><p>马克思的这个判定并非情绪化的攻击，而是基于他对洛克理论内核的解剖。</p><p>马克思认为，洛克所说的&quot;自然权利&quot;（生命、自由、财产），在现实社会中实际上只是<strong>资产阶级财产权的法权表达</strong>。洛克主张政府的目的是保护私有财产，但在马克思看来，这保护的只是有产者的利益。正如马克思所评价的：&quot;约翰·洛克是一切形式的新兴资产阶级的代表，他代表工厂主反对工人阶级和贫民，代表商人反对旧式高利贷者，代表金融贵族反对作为债务人的国家。&quot;</p><p>马克思认为，洛克的财产权理论本质上是为资本主义私有制提供合法性辩护。洛克认为劳动创造财产、财产先于政府存在，政府的目的就是保护财产。马克思认为这套逻辑掩盖了一个事实：在资本主义社会中，生产资料被少数人垄断，绝大多数人除了出卖劳动力之外一无所有。所谓的&quot;财产权&quot;对这些人来说只是一个空洞的形式。</p><p>马克思把洛克定位为&quot;资产阶级&quot;，是因为洛克的政治哲学成功地为资产阶级革命提供了理论武器，解决了把人从封建等级制中解放出来的&quot;政治解放&quot;，但它并没有、也不打算解决把人从资本主义剥削中解放出来的&quot;人类解放&quot;。</p><h3 id="马克思对卢梭的批判性吸收" tabindex="-1">马克思对卢梭的批判性吸收 <a class="header-anchor" href="#马克思对卢梭的批判性吸收" aria-label="Permalink to &quot;马克思对卢梭的批判性吸收&quot;">​</a></h3><p>马克思与卢梭的关系要复杂得多。马克思1843年在克罗伊茨纳赫做了大量的&quot;卢梭笔记&quot;，用法文摘录了《社会契约论》的核心内容。</p><p>马克思从卢梭那里借鉴了人民主权思想来批判黑格尔的王权思想，借鉴了卢梭对不平等的批判——卢梭在《论人类不平等的起源和基础》中揭示了私有制如何导致社会不平等，这个批判维度被马克思所吸收。马克思在&quot;卢梭笔记&quot;中围绕&quot;公意&quot;概念进行了重点摘录，将其作为理解社会契约基础的重要参考。</p><p>但马克思也对卢梭做了根本性的批判和超越：他用唯物史观超越了卢梭的&quot;道德政治&quot;——卢梭试图通过&quot;公意&quot;来重建道德与政治的统一，马克思认为这条路走不通，私利与公益的矛盾不是意志问题，而是财产权问题；他批判了卢梭的&quot;自然人&quot;概念，认为那不是超历史的抽象存在，而是特定社会关系的产物；他从&quot;政治解放&quot;走向&quot;人类解放&quot;，认为卢梭的目标只是建立资产阶级民主共和国，而不是真正的解放。</p><h3 id="三条线的思想谱系" tabindex="-1">三条线的思想谱系 <a class="header-anchor" href="#三条线的思想谱系" aria-label="Permalink to &quot;三条线的思想谱系&quot;">​</a></h3><p>把这三条思想线索放在一起，它们的关系是这样的：</p><ul><li><strong>洛克</strong>：资产阶级政治哲学的奠基者。核心命题是&quot;自然权利&quot;（生命、自由、财产）和&quot;有限政府&quot;。马克思要超越的对象。</li><li><strong>卢梭</strong>：对洛克传统的内部批判者。核心命题是&quot;公意&quot;和&quot;人民主权&quot;。他看到了洛克传统的缺陷——私有制导致不平等，形式自由掩盖实质不平等——但他的解决方案仍然在资产阶级政治哲学的框架内。马克思批判性吸收了他的不平等批判和人民主权思想，但用唯物史观超越了它的哲学前提。</li><li><strong>马克思</strong>：试图超越洛克和卢梭的整个资产阶级政治哲学框架。核心命题是&quot;人类解放&quot;——不是通过政治改革（洛克）或道德重建（卢梭），而是通过消灭私有制来实现。</li></ul><p>但这里有一个关键的悖论：<strong>马克思在超越卢梭的过程中，恰恰继承了卢梭思想中最危险的那个元素——&quot;公意&quot;的逻辑结构。</strong></p><p>卢梭说：存在一个超越所有私人利益的&quot;公意&quot;，它&quot;永远是正确的&quot;，服从它就是真正的自由。</p><p>马克思说：存在一个超越所有个体利益的&quot;无产阶级的历史使命&quot;，掌握这个使命的先锋队代表它，服从它就是历史的必然。</p><p>结构完全一样：先预设一个超越性的&quot;真正利益&quot;或&quot;历史规律&quot;，再指定一个主体来代表它，最后跳过&quot;谁来判定&quot;这个问题。卢森堡和罗素批评的正是这个结构——不管它披着&quot;公意&quot;的外衣还是&quot;历史规律&quot;的外衣，只要跳过了&quot;谁来审查审查者&quot;这个问题，它就为不受约束的权力打开了大门。</p><h2 id="九、致命的自负-马克思的人性观与制度设计的根基" tabindex="-1">九、致命的自负：马克思的人性观与制度设计的根基 <a class="header-anchor" href="#九、致命的自负-马克思的人性观与制度设计的根基" aria-label="Permalink to &quot;九、致命的自负：马克思的人性观与制度设计的根基&quot;">​</a></h2><h3 id="马克思能超越人性吗" tabindex="-1">马克思能超越人性吗？ <a class="header-anchor" href="#马克思能超越人性吗" aria-label="Permalink to &quot;马克思能超越人性吗？&quot;">​</a></h3><p>马克思确实认为自己设计了一套超越洛克和卢梭的哲学框架。他的核心方案是：不是通过政治改革（洛克）或道德重建（卢梭），而是通过消灭私有制、变革生产关系来实现&quot;人类解放&quot;。</p><p>这个方案的根基是马克思的人性观。马克思认为不存在永恒不变的抽象人性，&quot;人的本质不是单个人所固有的抽象物，在其现实性上，它是一切社会关系的总和&quot;。他认为人性自私、人性恶这些特征，不是人的自然属性，而是私有制社会的产物。&quot;什么样的总体社会关系背景，造就什么样的人性&quot;。</p><p>由此马克思推导出：既然人性是由社会关系决定的，那么只要通过革命消灭私有制、建立公有制，人性就会随之改变。在共产主义社会中，人将从&quot;史前史&quot;进入真正的&quot;人类历史&quot;，实现自由而全面的发展。</p><p>洛克传统的出发点是：<strong>人性是不可信任的</strong>——&quot;较为强壮或聪明的人通常企图剥夺弱者的生命、自由和财产&quot;。正因为人性不可信任，所以任何掌握权力的人都不可信任，制度设计的出发点就是防范权力被滥用。</p><p>马克思的人性观完全不同。他认为人性是可以被改造的，而改造的钥匙就在他手中——消灭私有制。</p><h3 id="致命的自负-逻辑的循环" tabindex="-1">&quot;致命的自负&quot;：逻辑的循环 <a class="header-anchor" href="#致命的自负-逻辑的循环" aria-label="Permalink to &quot;&quot;致命的自负&quot;：逻辑的循环&quot;">​</a></h3><p>马克思的这个逻辑存在一个致命的循环：为了证明革命是正当的，他必须预设一个未来的人性是可以被改造好的；为了证明先锋队有权垄断权力，他必须预设这个先锋队不会被权力腐蚀。但他无法证明这一点——他只能用&quot;历史规律&quot;来担保。</p><p>马克思认为人的本质是&quot;自由的有意识的活动&quot;即劳动，但在资本主义社会中人被异化了。他设想的共产主义是要实现&quot;人性的复归&quot;。但这种设想本身就建立在一个未经证明的预设之上：存在一个&quot;应有&quot;的人性，而且我们可以通过制度变革来实现它。</p><p>这正是洛克传统所拒绝的思维方式。洛克传统说：我不知道人性最终会变成什么样，但我知道现在的任何人都不可信任，所以权力必须受限。马克思说：我知道人性为什么现在是坏的（私有制），我也知道怎么让它变好（消灭私有制），所以只要让我掌握权力去改造社会，人性就会变好。</p><p><strong>谁更&quot;自负&quot;？一目了然。</strong></p><h3 id="哈耶克的解构-知识的分散性与理性的僭越" tabindex="-1">哈耶克的解构：知识的分散性与理性的僭越 <a class="header-anchor" href="#哈耶克的解构-知识的分散性与理性的僭越" aria-label="Permalink to &quot;哈耶克的解构：知识的分散性与理性的僭越&quot;">​</a></h3><p>这种&quot;致命的自负&quot;并非马克思一人的问题，而是一种深植于人类理性中的结构性倾向。哈耶克对这种倾向进行了最系统的认识论解构。</p><p>哈耶克的批判核心不是道德谴责，而是<strong>认识论上的不可能性</strong>。他认为乌托邦社会工程的失败不是因为执行者不够善良或不够聪明，而是因为它在逻辑上就不可能成功。</p><p><strong>知识的分散性。</strong> 哈耶克在1945年的经典论文《知识在社会中的运用》中提出了一个根本性命题：<strong>社会中最重要的知识，不是集中在某个专家或计划机构手中的&quot;科学知识&quot;，而是分散在无数个体手中的&quot;特定时空的知识&quot;（knowledge of the particular circumstances of time and place）。</strong></p><p>这种知识有几个关键特征：它是<strong>默会的</strong>——大量知识无法被编码、统计或传达，一个商人知道某种原材料在当地市场的微妙供需变化，一个工人知道某台机器的实际性能与说明书的差异，这些知识存在于日常实践中，无法被汇总到中央计划机构的表格里；它是<strong>局部的</strong>——每个人只知道自己所处环境中的信息，没有人能掌握全部信息；它是<strong>动态的</strong>——这些信息时刻在变化，昨天的最优决策今天可能已经过时。</p><p>哈耶克由此推导出：<strong>任何中央计划机构，无论它拥有多少专家、多先进的计算工具，都不可能收集和处理这些分散的、默会的、动态的知识。</strong> 因此，中央计划在认识论上就是不可能的——不是技术不够先进，而是问题本身的性质决定了它无法被解决。</p><p>市场价格机制恰恰是一种<strong>信息传递系统</strong>：价格浓缩了无数个体的局部知识，通过价格信号，每个人无需了解全局就能做出协调一致的决策。消灭市场、实行计划经济，等于摧毁了这个唯一能够处理分散知识的信息系统。</p><p><strong>理性的僭越。</strong> 哈耶克在1974年诺贝尔奖演讲《知识的僭妄》中进一步指出，现代社会科学犯了一个根本错误：<strong>把适用于自然科学的方法机械地套用到社会领域，误以为社会现象可以像物理现象一样被预测和控制。</strong> 他把这种做法称为&quot;科学主义的滥用&quot;。自然科学研究的是相对简单的、可重复的现象；社会现象是复杂的、由无数有意识的个体互动产生的，其复杂性远超任何单一心智的理解能力。声称自己能够&quot;科学地&quot;规划整个社会，是对人类理性能力的严重高估。</p><p>哈耶克区分了两种理性观：<strong>建构主义理性</strong>认为人类理性可以设计一切、控制一切、从零开始构建一个完美的社会秩序，这是笛卡尔传统的遗产，也是法国大革命和苏联计划经济的哲学根基；<strong>演化理性</strong>则认为人类文明中的许多制度——语言、法律、货币、市场——不是任何人设计的产物，而是在漫长的试错过程中自发演化出来的，这些制度包含了远超任何个体理性的集体智慧。</p><p>哈耶克的核心论点是：<strong>建构主义理性本身就是非理性的——因为它否认了理性的局限性。</strong> 真正的理性应该承认自己无法掌握全部知识，因此应该依赖那些在历史中经受住考验的自发秩序，而不是试图用人为设计取代它们。</p><p><strong>通往奴役之路。</strong> 在1944年的《通往奴役之路》中，哈耶克把上述认识论批判转化为政治警告。他的论证链条是：中央计划需要统一的目标体系，但现代社会中不存在所有人都认同的单一目标；为了推行计划，必须压制异议、统一思想、强制服从；经济控制必然导致全面控制——因为经济生活与其他一切生活领域不可分割；最终，计划经济不可避免地走向极权主义。</p><p>哈耶克特别强调：<strong>这不是说所有社会主义者都是极权主义者，而是说社会主义的逻辑终点是极权主义。</strong> 即使最初的动机是善良的，制度的内在逻辑也会把人推向那个方向。这正是他书名&quot;通往奴役之路&quot;的含义——不是目的地，而是道路本身。</p><h3 id="波普尔的解构-证伪主义与开放社会" tabindex="-1">波普尔的解构：证伪主义与开放社会 <a class="header-anchor" href="#波普尔的解构-证伪主义与开放社会" aria-label="Permalink to &quot;波普尔的解构：证伪主义与开放社会&quot;">​</a></h3><p>如果哈耶克从经济学和知识论的角度拆解了&quot;致命自负&quot;的认识论根基，那么卡尔·波普尔则从科学哲学的角度完成了同样的工作。他的核心武器是<strong>证伪主义</strong>。</p><p><strong>科学与伪科学的划界。</strong> 波普尔在《科学发现的逻辑》（1934年）中提出：科学理论的本质特征是<strong>可证伪性</strong>。一个理论如果是科学的，它就必须做出可以被经验检验的预测，而且这些预测有可能被证明是错误的。相反，如果一个理论无论发生什么情况都能自圆其说、永远不会被推翻，那它就不是科学，而是伪科学或形而上学。</p><p>波普尔举了两个著名例子：弗洛伊德的精神分析和马克思主义的历史唯物主义。无论工人阶级是否发动革命、无论资本主义是否崩溃，马克思主义者总能找到解释来说明&quot;历史规律&quot;仍然成立。这种&quot;永远正确&quot;恰恰是它不科学的标志。</p><p><strong>历史决定论的贫困。</strong> 在《历史决定论的贫困》（1957年）中，波普尔把证伪主义应用到历史领域。他批判的靶子是&quot;历史决定论&quot;——即认为历史发展遵循可被认识的客观规律，人类可以根据这些规律预测未来并据此设计社会。</p><p>波普尔的论证分三步：<strong>第一步</strong>，历史没有规律。自然现象之所以可以被预测，是因为它们遵循恒定的自然律。但历史是由人的行动构成的，而人的行动受知识的影响。人类知识本身在不断增长，我们无法预先知道未来会产生什么新知识，因此也无法预测历史的未来进程。<strong>第二步</strong>，整体预测是不可能的。即使某些局部趋势可以被识别，把它们加总为对整个社会未来的预测也是不可能的。社会是一个复杂系统，各部分之间的相互作用会产生涌现效应，无法从部分的性质推导出整体的走向。<strong>第三步</strong>，基于虚假预测的社会工程必然失败。既然历史规律不存在、整体预测不可能，那么任何声称依据&quot;历史规律&quot;来设计社会的方案，就建立在虚假的前提之上。这种方案不仅注定失败，而且因为它的不可证伪性，失败之后也无法被修正——信徒们总会找到理由来解释&quot;为什么还没成功&quot;。</p><p><strong>乌托邦社会工程与零星社会工程。</strong> 在《开放社会及其敌人》（1945年）中，波普尔区分了两种社会工程：<strong>乌托邦社会工程</strong>试图按照一个整体蓝图彻底重建社会，它预设了一个终极的善、一个完美的社会模型，然后动用一切手段去实现它，柏拉图的《理想国》、马克思的共产主义、纳粹的千年帝国都属于这一类；<strong>零星社会工程</strong>则针对具体的、可识别的社会问题进行小规模的、可修正的改革，它不预设终极目标，只关注眼前的苦难，允许试错，允许根据反馈调整方案，承认自己的可错性。</p><p>波普尔的核心论点是：<strong>乌托邦社会工程在方法论上是错误的，在政治上必然是暴力的。</strong> 方法论上的错误在于：它把社会当作一个可以按照蓝图重新设计的机器，忽视了社会的复杂性和人类知识的局限性。正如哈耶克所说，分散的知识无法被集中；正如波普尔所说，整体的预测不可能实现。政治上的暴力在于：乌托邦蓝图不可能获得所有人的一致同意，所以必须通过强制手段来推行；当现实与蓝图不符时，不是修改蓝图，而是消灭那些&quot;阻碍蓝图实现&quot;的人；为了维护蓝图的纯洁性，必须压制批评、禁止异议、控制思想。</p><p>波普尔写道：&quot;乌托邦工程师的态度是：清扫画布，从头再来。但这种态度本身就蕴含着暴力——因为画布上已经有人了。&quot;</p><p><strong>开放社会的认识论根基。</strong> 波普尔的&quot;开放社会&quot;概念直接来自他的证伪主义。开放社会的本质特征是：<strong>承认没有人掌握终极真理，因此必须保障批评的自由、思想的竞争、制度的可修正性。</strong> 封闭社会则相反：它声称掌握了终极真理（无论是神谕、历史规律还是领袖意志），因此不允许批评、不允许异议、不允许制度被挑战。</p><p>波普尔指出，从封闭社会向开放社会的过渡是人类历史上最深刻的变革之一，但这个过渡从未完成，也永远不会完成。每一次声称&quot;我们已经找到了终极答案&quot;的时刻，都是向封闭社会的倒退。</p><h3 id="两条线索的交汇" tabindex="-1">两条线索的交汇 <a class="header-anchor" href="#两条线索的交汇" aria-label="Permalink to &quot;两条线索的交汇&quot;">​</a></h3><p>哈耶克和波普尔的论证路径不同，但在几个关键点上形成了完美的互补：</p><p>哈耶克波普尔批判起点知识的分散性证伪主义核心命题中央计划在认识论上不可能历史决定论在方法论上错误对理性的态度演化理性优于建构理性可错性是理性的本质特征替代方案自发秩序、市场价格机制零星社会工程、开放社会政治推论计划经济通往奴役乌托邦工程通往暴力共同敌人建构主义理性、整体主义、对权力的迷信两人的共同洞见可以概括为一句话：<strong>人类理性是有限的、可错的，任何声称超越这种局限性的尝试，不仅在认识论上是虚妄的，在政治上必然是暴力的。</strong></p><p>这个洞见直接回应了本章的核心问题：为什么马克思虽然深刻批判了洛克传统，但他自己的方案却导致了更大的灾难？答案就在于：马克思（以及后来的列宁）恰恰陷入了哈耶克所说的&quot;建构主义理性&quot;和波普尔所说的&quot;历史决定论&quot;——他们相信自己掌握了历史的规律，相信自己有能力设计一个完美的社会，相信只要掌握了权力就可以按照蓝图改造人性。这种自信本身就是通往灾难的快车道。</p><h3 id="一个必要的澄清-他们不是保守主义者" tabindex="-1">一个必要的澄清：他们不是保守主义者 <a class="header-anchor" href="#一个必要的澄清-他们不是保守主义者" aria-label="Permalink to &quot;一个必要的澄清：他们不是保守主义者&quot;">​</a></h3><p>需要澄清一个常见的误解：哈耶克和波普尔并不是反对一切社会改革，也不是在为现状辩护。</p><p>哈耶克明确支持社会保障、公共教育、环境保护等政府职能，他反对的不是政府干预本身，而是那种声称可以按照整体蓝图重构社会的干预。他说：&quot;我从来不是一个无政府主义者。我只是认为政府的权力应该受到限制，而且应该以一般性的规则而非特定的命令来行使。&quot;</p><p>波普尔同样明确支持福利国家、社会正义、消除贫困等改革目标。他说：&quot;零星社会工程的目的不是建立一个完美的社会，而是减少具体的、可识别的苦难。&quot;他反对的不是改革本身，而是那种以&quot;完美社会&quot;为名取消批评自由的改革。</p><p>两人的立场可以这样概括：<strong>他们是改革的拥护者，但是是谦逊的改革者——承认自己的可错性，允许试错，允许纠错，不把任何蓝图神圣化。</strong> 这种谦逊，恰恰是洛克传统的精髓，也是马克思-列宁传统所缺失的东西。</p><h3 id="马克思有建设性吗" tabindex="-1">马克思有建设性吗？ <a class="header-anchor" href="#马克思有建设性吗" aria-label="Permalink to &quot;马克思有建设性吗？&quot;">​</a></h3><p>说马克思&quot;没有什么建设性的&quot;，这个判断需要分两面看。</p><p><strong>作为批判者，马克思极具建设性。</strong> 他对资本主义的批判——贫富两极分化、人的异化、经济危机的周期性——在19世纪是极其深刻的。正是马克思的批判，迫使资本主义世界进行了自我修正：八小时工作制、社会保障体系、累进税制、工会权利——这些都不是资本家自愿给的，而是工人阶级斗争的结果，而马克思为这种斗争提供了理论武器。</p><p><strong>但作为制度设计者，马克思的建设性是缺失的。</strong> 他告诉我们要消灭私有制，但没说消灭之后怎么防止权力垄断；他告诉我们要实现人类解放，但没说解放的过程中怎么防止解放者变成新的压迫者。</p><p>马克思的理论中缺少一个关键环节：<strong>对权力本身的警惕。</strong> 他相信只要权力掌握在&quot;正确的人&quot;（无产阶级、先锋队）手中，权力就不会被滥用。这种对权力的天真，正是后来所有灾难的根源。</p><h2 id="十、为什么-资产阶级政治哲学-反而稳定运行" tabindex="-1">十、为什么&quot;资产阶级政治哲学&quot;反而稳定运行？ <a class="header-anchor" href="#十、为什么-资产阶级政治哲学-反而稳定运行" aria-label="Permalink to &quot;十、为什么&quot;资产阶级政治哲学&quot;反而稳定运行？&quot;">​</a></h2><p>今天世界上所有基于马克思思想过度自信而建立的制度——苏联、东欧、柬埔寨、朝鲜——无一例外地走向了灾难或困境。而基于洛克传统的&quot;资产阶级政治哲学&quot;建立的制度，虽然问题重重，却仍在稳定运行。这是为什么？</p><p>答案在于两套制度对&quot;错误&quot;的不同态度。</p><p>洛克传统的核心不是&quot;资产阶级&quot;，而是<strong>对权力的不信任</strong>。</p><p>洛克传统说：我不知道什么是终极的善，我不知道人性最终会变成什么样，但我知道任何掌握权力的人都可能滥用权力，所以我设计一套制度来限制权力、分散权力、让权力可以被挑战。</p><p>这套制度不依赖于&quot;好人执政&quot;，不预设任何终极真理，它承认自己的可错性，允许不同观点自由竞争，允许通过程序来纠错。正因为它的&quot;低姿态&quot;，它反而能够适应各种复杂情况，在时间的考验中存活下来。</p><p>马克思传统的核心是：<strong>我知道终极的善是什么（共产主义），我知道历史规律是什么（唯物史观），所以我的权力不需要被限制——因为我在执行历史的意志。</strong></p><p>这套制度高度依赖&quot;好人执政&quot;，一旦掌权者出了问题（腐败、僵化、脱离群众），没有任何制度化的机制可以纠正它。正因为它的&quot;高姿态&quot;，它反而在现实面前碰得头破血流。</p><p>美国制度在两百多年里经历了内战、经济大萧条、麦卡锡主义、水门事件、2008年金融危机等无数次危机，每次都通过制度内部的机制完成了纠错——法院推翻违宪的法律、选举更换不称职的领导人、媒体曝光腐败行为、公民社会施加压力。</p><p>苏联制度在七十多年里积累的问题——经济僵化、官僚腐败、民族矛盾、意识形态空心化——没有任何制度化的渠道可以释放和解决。戈尔巴乔夫试图改革时，发现整个制度缺乏弹性，一松手就散了。</p><p><strong>一个能自我纠错的制度，和一个只能等到崩溃才能&quot;纠错&quot;的制度，长期稳定性天差地别。</strong></p><p>而洛克传统之所以更稳定，恰恰因为它内在地包含了哈耶克和波普尔所强调的那些要素：对理性局限的承认、对分散知识的尊重、对制度可修正性的保障、对权力垄断的警惕。洛克本人当然没有使用&quot;证伪主义&quot;或&quot;分散知识&quot;这些术语，但他的制度设计在功能上实现了这些原则。</p><h2 id="十一、历史的验证" tabindex="-1">十一、历史的验证 <a class="header-anchor" href="#十一、历史的验证" aria-label="Permalink to &quot;十一、历史的验证&quot;">​</a></h2><p>卢森堡于1919年1月15日被右翼民兵杀害，未能亲眼看到她的预言一一实现。但她关于先锋队异化的警告，在苏联后来的历史中得到了惊人的印证：</p><ul><li>1921年，俄共十大禁止党内派别活动——&quot;临时&quot;禁令直到1989年才解除；</li><li>斯大林时期，大清洗消灭了几乎所有老布尔什维克，先锋队从&quot;代表人民&quot;变成了&quot;统治人民&quot;；</li><li>1977年，苏联宪法第六条将苏共的领导地位写入宪法——先锋队从&quot;革命组织&quot;变成了&quot;宪法特权阶层&quot;；</li><li>苏联晚期，官僚特权阶层（nomenklatura）形成了一个封闭的利益集团，与普通群众完全脱节。</li></ul><p>卢森堡1918年在狱中写下的那段话——&quot;公共生活逐渐沉睡，几十个精力无穷的党的领导人指挥着和统治着&quot;——几乎就是苏联政治体制的精确素描。</p><p>而哈耶克和波普尔的预言同样得到了验证。哈耶克在1944年警告的&quot;通往奴役之路&quot;，在此后半个世纪的苏联、东欧、东亚反复上演。波普尔在1945年批判的&quot;乌托邦社会工程&quot;，在柬埔寨红色高棉的&quot;零年&quot;实验中达到了最极端的形态——波尔布特试图按照蓝图彻底重建社会，结果在四年内杀死了本国近四分之一的人口。</p><p>这些不是&quot;执行偏差&quot;，而是逻辑的必然。正如波普尔所说：当蓝图与现实不符时，乌托邦工程师的选择不是修改蓝图，而是消灭那些&quot;阻碍蓝图实现&quot;的人。</p><h2 id="十二、一个讽刺的注脚" tabindex="-1">十二、一个讽刺的注脚 <a class="header-anchor" href="#十二、一个讽刺的注脚" aria-label="Permalink to &quot;十二、一个讽刺的注脚&quot;">​</a></h2><p>1950年代，中国在思想文化领域开展了一系列对&quot;资产阶级唯心主义&quot;的批判运动。罗素也在这波批判的射程之内。1957年，上海人民出版社出版了朱宝昌编著的《分析批评罗素哲学的纯客观主义态度》，专门运用阶级分析的手法批判罗素哲学，说他属于巴克莱和休谟的主观唯心主义阵营，否认辩证逻辑，导致哲学观点的狭隘性。</p><p>这场批判的荒诞之处在于：<strong>批判者用来批判罗素的工具，恰恰是罗素所反对的那套思维方式——预先下结论，再找论据。</strong> 罗素批评托马斯·阿奎那的话用在这里同样适用：阿奎那预先假定基督教是真的，然后去找论证；批判者预先假定马克思主义是对的，然后去找论据。两者都不是从&quot;不带预设的理性探究&quot;出发，而是从&quot;先有结论再找支撑&quot;出发。罗素把这种做法叫做&quot;诡辩&quot;而不是&quot;哲学&quot;。</p><p>更有讽刺意味的是，罗素早在1920年访苏之后就精准预见了苏联体制的致命缺陷——而这些缺陷在几十年后全部应验了。批判他的人所捍卫的那套制度，恰恰就是罗素所批评的那套制度。</p><h2 id="十三、回到那个最根本的问题" tabindex="-1">十三、回到那个最根本的问题 <a class="header-anchor" href="#十三、回到那个最根本的问题" aria-label="Permalink to &quot;十三、回到那个最根本的问题&quot;">​</a></h2><p>回到本文的起点：列宁生于洛克之后两百多年，为什么洛克传统的制度反而更稳定、更具韧性、更能经受住时间的考验？</p><p>答案不在于谁先谁后，而在于两套思想对<strong>权力</strong>和<strong>人</strong>的根本假设不同。洛克传统从&quot;人不值得信任&quot;出发，设计了一套不依赖&quot;好人&quot;就能运转的制度；卢梭-马克思-列宁传统从&quot;先锋队值得信任&quot;出发，设计了一套高度依赖&quot;好人&quot;才能运转的制度。前者在时间的考验面前更经得起折腾，因为它不假设任何人——包括立法者、执法者、先锋队——是永远正确的。</p><p>马克思批评洛克是&quot;资产阶级&quot;，但他自己设计的方案却导致了比资产阶级专政更可怕的权威——一个垄断了经济、政治、思想所有领域的极权国家。这确实是一个巨大的历史讽刺。</p><p>哈耶克和波普尔从两个不同的方向——经济学与科学哲学——得出了同一个结论：<strong>人类理性是有限的、可错的，任何声称超越这种局限性的尝试，不仅在认识论上是虚妄的，在政治上必然是暴力的。</strong> 洛克传统之所以稳定，不是因为它是&quot;资产阶级&quot;的，而是因为它内在地承认了这种局限性。卢梭-列宁传统之所以失败，不是因为它追求&quot;更高的理想&quot;，而是因为它拒绝承认这种局限性。</p><p>罗素一生所做的，就是不断地追问那个别人不愿意追问的问题：<strong>当你声称代表&quot;公意&quot;或&quot;人民利益&quot;的时候，谁来审查你？如果答案是&quot;不需要审查&quot;，那你的权力就跟专制君主没有区别——只不过你换了一套说辞而已。</strong></p><p>卢森堡从革命阵营内部发出了同样的追问：<strong>当先锋队垄断了权力，它还是无产阶级的代表吗？当自由只给执政者，它还叫自由吗？</strong></p><p>这个问题，两百年前洛克问过，两百年后罗素又问了一遍，卢森堡在狱中又问了一遍，哈耶克和波普尔从知识论和科学哲学的角度又问了一遍。而那些不愿意回答这个问题的人，恰恰证明了这个问题为什么必须被不断地追问下去。</p><hr><blockquote><p>本文同步自知乎，<a href="https://zhuanlan.zhihu.com/p/2076270323851321858" target="_blank" rel="noreferrer">查看原文</a>（2 赞）</p></blockquote>',212)])])}const c=t(r,[["render",p]]);export{g as __pageData,c as default};
